-- PREPARED -- NOT APPLIED.
--
-- NL: fill missing Google Place IDs, phone numbers and websites
-- (export of 2026-10-31). Generated by europe_gaps/build_gap_fill_sql.py from the
-- reviewed research in the matching *_gap_fill.csv (evidence and the reason
-- per row, including every value held back).
--
-- Fill-only: a value is written only where the field is NULL; nothing is
-- overwritten. Place ID: the venue's own Google record (restaurant, or
-- lodging for a hotel), within 100 m of the stored point, or 100-500 m with
-- the official domain; never a hotel's record for a named restaurant inside
-- it. Phone: MICHELIN and Google agreeing, or the number printed on the
-- official site. Website: MICHELIN's link and the Google record agreeing on
-- the domain, or a site that loads and names the restaurant.
--
-- One transaction; any failed check rolls the whole file back. Safe to
-- re-run (fill-only).

begin;
-- restaurants: 10 rows (2 Place IDs, 8 phones, 0 websites)
create temp table _fill_restaurant (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_restaurant values
    ('rest_0028', 'CUE', NULL, '+31 20 205 1332', NULL),
    ('rest_0031', 'De Heeren van Harinxma', NULL, '+31 512 381 245', NULL),
    ('rest_0043', 'Demain', NULL, '+31 117 392 110', NULL),
    ('rest_0055', 'Karel 5', NULL, '+31 30 233 7555', NULL),
    ('rest_0062', 'Lizz', NULL, '+31 182 231 253', NULL),
    ('rest_0114', 'Vinkeles', NULL, '+31 20 530 2010', NULL),
    ('rest_0115', 'Vista', NULL, '+31 168 852 212', NULL),
    ('rest_0116', 'Voltaire', NULL, '+31 343 745 858', NULL),
    ('rest_1840', 'Tacite', 'ChIJ1SjszrvjxUcR4W7mTHjRiVU', NULL, NULL),
    ('rest_1841', 'Petit Péché', 'ChIJ45WdSb3jxUcRLApSW6aPcbg', NULL, NULL);

do $$
declare bad text;
begin
  -- identity: each code must still be the NL row of that name
  select string_agg(f.code, ', ') into bad from _fill_restaurant f
   where not exists (select 1 from public.restaurants x where x.restaurant_code = f.code and x.name = f.name and x.country_code = 'NL');
  if bad is not null then raise exception 'restaurants: code is no longer the exported NL row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.restaurant_code || ')', '; ') into bad
    from _fill_restaurant f join public.restaurants x on x.google_place_id = f.place_id and x.restaurant_code <> f.code;
  if bad is not null then raise exception 'restaurants: Place ID already used by another row: %', bad; end if;
end $$;

update public.restaurants x set google_place_id = f.place_id, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.restaurants x set phone = f.phone, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.phone is not null and x.phone is null;
update public.restaurants x set website_url = f.website, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.website is not null and x.website_url is null;

-- hotels: 1 rows (1 Place IDs, 1 phones, 1 websites)
create temp table _fill_hotel (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_hotel values
    ('hotel_2808', 'De Durgerdam', 'ChIJO6YAXocPxkcR7qoKAmb1UKs', '+31 20 218 4463', 'https://www.dedurgerdam.com/?utm_source=google&utm_medium=gmb&utm_campaign=gmb');

do $$
declare bad text;
begin
  -- identity: each code must still be the NL row of that name
  select string_agg(f.code, ', ') into bad from _fill_hotel f
   where not exists (select 1 from public.hotels x where x.hotel_code = f.code and x.name = f.name and x.country_code = 'NL');
  if bad is not null then raise exception 'hotels: code is no longer the exported NL row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.hotel_code || ')', '; ') into bad
    from _fill_hotel f join public.hotels x on x.google_place_id = f.place_id and x.hotel_code <> f.code;
  if bad is not null then raise exception 'hotels: Place ID already used by another row: %', bad; end if;
end $$;

update public.hotels x set google_place_id = f.place_id, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.hotels x set phone = f.phone, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.phone is not null and x.phone is null;
update public.hotels x set website_url = f.website, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.website is not null and x.website_url is null;

commit;
